using System;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[Serializable]
public class EventButtonData
{
	public EventAction eventAction;

	[SerializeField]
	private bool disableResultText;

	[SerializeField]
	private bool enableCustomEventButtonDataIDIndex;

	[SerializeField]
	[ShowIf("enableCustomEventButtonDataIDIndex")]
	[AllowNesting]
	private int eventButtonDataIDIndex;

	[SerializeField]
	protected bool ignoreFirstButtonClickLogicAndUpdateEventDescriptionAndButtons;

	[SerializeField]
	[ShowIf("ignoreFirstButtonClickLogicAndUpdateEventDescriptionAndButtons")]
	[AllowNesting]
	private bool instantlyUpdate = true;

	private string loreTextID;

	private string resultTextID;

	public bool IgnoreFirstButtonClickLogicAndUpdateEventDescriptionAndButtons => ignoreFirstButtonClickLogicAndUpdateEventDescriptionAndButtons;

	public bool InstantlyUpdate => instantlyUpdate;

	public void SetLoreTextID(string loreTextID)
	{
		this.loreTextID = loreTextID;
	}

	public void SetResultTextID(string resultTextID)
	{
		this.resultTextID = resultTextID;
	}

	public bool IsEventButtonEnabled()
	{
		return eventAction.IsEventButtonEnabled();
	}

	public string GetEventButtonLoreText()
	{
		if (eventAction.UseResultTextOnLoreTextAndDisableResultText)
		{
			return GetEventButtonResultTextFinal();
		}
		if (eventAction.EnableCustomEventButtonLoreText)
		{
			return eventAction.GetEventButtonLoreText(loreTextID);
		}
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(loreTextID);
	}

	public string GetEventButtonResultText()
	{
		if (disableResultText || eventAction.UseResultTextOnLoreTextAndDisableResultText)
		{
			return "";
		}
		return GetEventButtonResultTextFinal();
	}

	public string GetEventButtonResultTextFinal()
	{
		if (eventAction.EnableCustomEventButtonResultText)
		{
			return eventAction.GetEventButtonResultText(resultTextID);
		}
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(resultTextID);
	}

	public int GetEventButtonDataIDIndex(int buttonIndex)
	{
		if (enableCustomEventButtonDataIDIndex)
		{
			return eventButtonDataIDIndex;
		}
		return buttonIndex;
	}
}
